```python
import shutil
import openpyxl
import datetime

try:
    from openpyxl.utils.datetime import from_excel
except Exception:
    from_excel = None

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "output" not in wb.sheetnames:
    ws_out = wb.create_sheet("output")
else:
    ws_out = wb["output"]

ws_in = vals["input"]

def strip_text(v):
    if v is None:
        return None
    s = str(v).strip()
    return s if s else None

def to_datetime(v):
    if v is None:
        return None
    if isinstance(v, datetime.datetime):
        return v
    if isinstance(v, datetime.date):
        return datetime.datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)):
        if from_excel is not None:
            try:
                return from_excel(v)
            except Exception:
                pass
        try:
            import pandas as pd
            return pd.Timestamp(v, unit="D", origin="1899-12-30").to_pydatetime()
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%Y/%m/%d %H:%M:%S",
            "%Y/%m/%d",
            "%d-%m-%Y",
            "%d/%m/%Y",
            "%m/%d/%Y",
        ):
            try:
                return datetime.datetime.strptime(s, fmt)
            except ValueError:
                pass
        try:
            import pandas as pd
            return pd.to_datetime(s).to_pydatetime()
        except Exception:
            return None
    return None

def to_num(v):
    if v is None:
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None

def is_neg(v):
    n = to_num(v)
    return n is not None and n < 0

def clean_number(v):
    if v is None or isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        f = float(v)
        return int(f) if f.is_integer() else f
    if isinstance(v, str):
        s = v.strip()
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
            return s
    return v

records = []
for r in range(2, ws_in.max_row + 1):
    d = to_datetime(ws_in.cell(r, 1).value)
    s = strip_text(ws_in.cell(r, 2).value)
    o = ws_in.cell(r, 3).value
    h = ws_in.cell(r, 4).value
    l = ws_in.cell(r, 5).value
    c = ws_in.cell(r, 6).value
    v = ws_in.cell(r, 7).value
    ch = ws_in.cell(r, 8).value

    if all(x is None for x in (d, s, o, h, l, c, v, ch)):
        continue

    records.append({
        "date": d,
        "stock": s,
        "open": o,
        "high": h,
        "low": l,
        "close": c,
        "volume": v,
        "change": ch,
    })

out_rows = []
i = 0
while i < len(records):
    rec = records[i]

    if rec["stock"] is None:
        i += 1
        continue

    if is_neg(rec["change"]):
        j = i
        while (
            j + 1 < len(records)
            and records[j + 1]["stock"] == rec["stock"]
            and is_neg(records[j + 1]["change"])
        ):
            j += 1

        run = records[i:j + 1]
        dated = [x for x in run if x["date"] is not None]

        if dated:
            first = min(dated, key=lambda x: x["date"])
            last = max(dated, key=lambda x: x["date"])
            date_out = last["date"]
        else:
            first = run[-1]
            last = run[0]
            date_out = last["date"]

        highs = [to_num(x["high"]) for x in run]
        highs = [x for x in highs if x is not None]

        lows = [to_num(x["low"]) for x in run]
        lows = [x for x in lows if x is not None]

        vols = [to_num(x["volume"]) for x in run]
        vols = [x for x in vols if x is not None]

        out_rows.append({
            "date": date_out,
            "stock": rec["stock"],
            "open": first["open"],
            "high": max(highs) if highs else None,
            "low": min(lows) if lows else None,
            "close": last["close"],
            "volume": sum(vols) if vols else None,
        })

        i = j + 1
    else:
        out_rows.append({
            "date": rec["date"],
            "stock": rec["stock"],
            "open": rec["open"],
            "high": rec["high"],
            "low": rec["low"],
            "close": rec["close"],
            "volume": rec["volume"],
        })
        i += 1

for r in range(2, 16):
    for c in range(1, 8):
        ws_out.cell(r, c).value = None

for idx, rec in enumerate(out_rows):
    r = 2 + idx
    ws_out.cell(r, 1).value = rec["date"]
    ws_out.cell(r, 2).value = rec["stock"]
    ws_out.cell(r, 3).value = clean_number(rec["open"])
    ws_out.cell(r, 4).value = clean_number(rec["high"])
    ws_out.cell(r, 5).value = clean_number(rec["low"])
    ws_out.cell(r, 6).value = clean_number(rec["close"])
    ws_out.cell(r, 7).value = clean_number(rec["volume"])

wb.save(OUT)

print("rows:", len(out_rows))
for rec in out_rows[:3]:
    print(rec["date"], rec["stock"], rec["open"], rec["high"], rec["low"], rec["close"], rec["volume"])
